// LLM-Kompass: Daten aus Artificial Analysis und Arena zusammenführen und mit Notion abgleichen
const DB_ID = 'f88e12ef13ba4246950a944e13637bde';
const MAX_AA = 40;      // beste Modelle nach Intelligence Index
const MAX_ARENA = 40;   // beste Modelle nach Arena-Score
// Manuelle Zuordnung, falls Namen in beiden Quellen unterschiedlich geschrieben werden: 'quellschluessel': 'zielschluessel'
const ALIAS = {};

const today = new Date().toISOString().slice(0, 10);
const norm = s => { const k = String(s || '').toLowerCase().replace(/\([^)]*\)/g, '').replace(/[^a-z0-9]/g, ''); return ALIAS[k] || k; };
const clean = s => String(s || '').replace(/\s*\([^)]*\)\s*/g, ' ').replace(/\s+/g, ' ').trim();
const num = v => { if (v === null || v === undefined || v === '') return null; const n = Number(v); return isFinite(n) ? n : null; };
const pick = (o, paths) => { for (const p of paths) { const v = p.split('.').reduce((a, k) => (a == null ? undefined : a[k]), o); if (v !== undefined && v !== null && v !== '') return v; } return null; };
const round = (v, d) => (v == null ? null : Math.round(v * 10 ** d) / 10 ** d);

// 1. Artificial Analysis (Free API)
const aaRaw = $('Artificial Analysis – LLMs').first().json;
const aaList = Array.isArray(aaRaw.data) ? aaRaw.data : Array.isArray(aaRaw.models) ? aaRaw.models : Array.isArray(aaRaw) ? aaRaw : [];
if (!aaList.length) throw new Error('Artificial Analysis: keine Modelle erhalten. API-Schlüssel und Antwortformat prüfen.');
const aa = new Map();
for (const m of aaList) {
  const name = pick(m, ['name', 'model_name', 'slug']);
  const key = norm(name);
  if (!key) continue;
  const rec = {
    name: clean(name),
    creator: pick(m, ['model_creator.name', 'creator.name', 'model_creator', 'creator']),
    intel: num(pick(m, ['evaluations.artificial_analysis_intelligence_index', 'indices.intelligence', 'intelligence_index'])),
    coding: num(pick(m, ['evaluations.artificial_analysis_coding_index', 'indices.coding', 'coding_index'])),
    agentic: num(pick(m, ['evaluations.artificial_analysis_agentic_index', 'indices.agentic', 'agentic_index'])),
    pin: num(pick(m, ['pricing.price_1m_input_tokens', 'pricing.input', 'price_1m_input_tokens'])),
    pout: num(pick(m, ['pricing.price_1m_output_tokens', 'pricing.output', 'price_1m_output_tokens'])),
    speed: num(pick(m, ['median_output_tokens_per_second', 'performance.median_output_tokens_per_second', 'output_speed'])),
  };
  const prev = aa.get(key);
  if (!prev || (rec.intel ?? -1) > (prev.intel ?? -1)) aa.set(key, rec);
}

// 2. Arena Leaderboard Dataset (Hugging Face, CC BY 4.0)
const arRaw = $('Arena – Text (Style Control)').first().json;
const arRows = (arRaw.rows || []).map(r => r.row || r);
const arena = new Map();
let arenaDate = '';
for (const r of arRows) {
  if (r.category && r.category !== 'overall') continue;
  const key = norm(r.model_name);
  const rating = num(r.rating);
  if (!key || rating == null) continue;
  arenaDate = r.leaderboard_publish_date || arenaDate;
  const prev = arena.get(key);
  if (!prev || rating > prev.rating) arena.set(key, { name: clean(r.model_name), org: r.organization, license: r.license, rating });
}
if (!arena.size) throw new Error('Arena: keine Daten erhalten. Datensatz-Abfrage prüfen.');

// 3. Auswahl: Spitzenfeld aus beiden Quellen
const topAA = [...aa.entries()].filter(([, v]) => v.intel != null).sort((a, b) => b[1].intel - a[1].intel).slice(0, MAX_AA).map(([k]) => k);
const topAR = [...arena.entries()].sort((a, b) => b[1].rating - a[1].rating).slice(0, MAX_ARENA).map(([k]) => k);
const keys = [...new Set([...topAA, ...topAR])];

// 4. Bestehende Notion-Einträge
const existing = new Map();
for (const it of $input.all()) {
  const j = it.json || {};
  if (!j.id || !j.properties) continue;
  const p = j.properties;
  const keyTxt = (p['Schlüssel']?.rich_text || []).map(t => t.plain_text).join('');
  const title = (p['Modell']?.title || []).map(t => t.plain_text).join('');
  existing.set(keyTxt || norm(title), { id: j.id, aktiv: p['Aktiv']?.checkbox === true });
}

const origin = s => {
  const o = String(s || '').toLowerCase();
  if (/(anthropic|openai|google|meta|xai|spacex|amazon|microsoft|nvidia|ibm|thinky|thinking machines|cohere|ai2|inception)/.test(o)) return 'USA';
  if (/(xiaomi|alibaba|qwen|zai|z\.ai|zhipu|deepseek|moonshot|kimi|tencent|minimax|stepfun|baidu|bytedance|meituan|ant group|inclusion)/.test(o)) return 'China';
  if (/(mistral|aleph|black forest)/.test(o)) return 'EU';
  return 'Andere';
};
const openness = lic => {
  const l = String(lic || '').toLowerCase();
  if (!l) return null;
  if (l.includes('propriet')) return 0;
  if (/^(mit|apache)/.test(l)) return 1;
  return 0.7;
};
const rt = v => ({ rich_text: [{ type: 'text', text: { content: String(v).slice(0, 1900) } }] });
const setNum = (props, name, v) => { if (v != null) props[name] = { number: v }; };

const out = [];
for (const key of keys) {
  const a = aa.get(key), r = arena.get(key);
  const props = {};
  const name = a?.name || r?.name;
  const creator = r?.org || a?.creator;
  props['Schlüssel'] = rt(key);
  if (creator) props['Anbieter'] = rt(String(creator).charAt(0).toUpperCase() + String(creator).slice(1));
  if (creator) props['Herkunft'] = { select: { name: origin(creator) } };
  if (r?.license) { props['Lizenz'] = rt(r.license); props['Offen'] = { number: openness(r.license) }; }
  setNum(props, 'Intelligenz', round(a?.intel, 1));
  setNum(props, 'Coding', round(a?.coding, 1));
  setNum(props, 'Agentik', round(a?.agentic, 1));
  setNum(props, 'Arena', round(r?.rating, 0));
  setNum(props, 'Tempo', round(a?.speed, 0));
  setNum(props, 'Preis In', a?.pin);
  setNum(props, 'Preis Out', a?.pout);
  props['Quelle'] = rt([a ? 'Artificial Analysis' : null, r ? 'Arena ' + arenaDate : null].filter(Boolean).join(' + '));
  props['Stand'] = { date: { start: today } };
  props['Aktiv'] = { checkbox: true };

  const ex = existing.get(key);
  if (ex) {
    out.push({ json: { action: 'update', Modell: name, method: 'PATCH', url: 'https://api.notion.com/v1/pages/' + ex.id, body: { properties: props } } });
  } else {
    props['Modell'] = { title: [{ type: 'text', text: { content: name } }] };
    out.push({ json: { action: 'create', Modell: name, method: 'POST', url: 'https://api.notion.com/v1/pages', body: { parent: { database_id: DB_ID }, properties: props } } });
  }
}

// 5. Nicht mehr gefundene Modelle deaktivieren (nicht löschen)
for (const [key, ex] of existing) {
  if (!keys.includes(key) && ex.aktiv) {
    out.push({ json: { action: 'deactivate', Modell: key, method: 'PATCH', url: 'https://api.notion.com/v1/pages/' + ex.id, body: { properties: { 'Aktiv': { checkbox: false } } } } });
  }
}
return out;
